package com.internalops.workbench;
import com.internalops.api.ApiResponse;import org.springframework.http.ResponseEntity;import org.springframework.web.bind.annotation.*;import java.util.Map;
@RestController public class FulfillmentController{private final FulfillmentService s;public FulfillmentController(FulfillmentService s){this.s=s;}@PostMapping("/api/orders/{id}/ship")public ApiResponse<Map<String,Object>> ship(@PathVariable long id,@RequestBody FulfillmentService.ShippingRequest r){return ApiResponse.ok(s.ship(id,r));}@ExceptionHandler(IllegalArgumentException.class)ResponseEntity<ApiResponse<Object>> bad(IllegalArgumentException e){return ResponseEntity.badRequest().body(new ApiResponse<>(false,null,e.getMessage()));}@ExceptionHandler(IllegalStateException.class)ResponseEntity<ApiResponse<Object>> conflict(IllegalStateException e){return ResponseEntity.status(409).body(new ApiResponse<>(false,null,e.getMessage()));}}
